import { headers } from "next/headers";
import { fallbackLng, supported } from "./i18n.resources";

/**
 * Generated by localize.dev: hreflang links to this page in every language, for search engines.
 * React hoists them into <head>. The path comes from the generated proxy.
 */
export async function LanguageAlternates() {
  const h = await headers();
  const host = h.get("x-forwarded-host") ?? h.get("host");
  const path = h.get("x-localize-path");
  if (!host || !path) return null;
  const origin = `${h.get("x-forwarded-proto") ?? "https"}://${host}`;
  const url = (lng: string) => (lng === fallbackLng ? `${origin}${path}` : `${origin}/${lng}${path === "/" ? "" : path}`);
  return (
    <>
      {supported.map((lng) => (
        <link key={lng} rel="alternate" hrefLang={lng} href={url(lng)} />
      ))}
      <link rel="alternate" hrefLang="x-default" href={url(fallbackLng)} />
    </>
  );
}
